---------------- Aviso 1 ----------------
-- El contenido de las tablas de clientes (clients) y pedidos (orders) se ha generado aleatoriamente vía scripts de Python.
---------------- Aviso 2 ----------------
-- El contenido de la tabla de libros (products) se ha generado vía consulta a Google Gemini.
-- Existe la posibilidad de que los autores, libros y precios en pesos argentinos no coincidan uno a uno con la realidad.
---------------- Aviso 3 ----------------
-- Dado que son datos sintéticos, no fue necesario realizar limpieza de datos nulos.
-- Más aún, el diseño de las tablas no admiten estos casos.

-- lista de clientes
drop table if exists clients cascade;
create table clients (
    client_id serial primary key, -- id de cliente siendo clave primaria
    name varchar(100) not null, -- nombre del cliente
    birthdate date not null, -- fecha de nacimiento
	email varchar(100) not null, -- email
	phone varchar(30) not null -- número de teléfono
);

-- lista de productos
drop table if exists products cascade;
create table products (
    product_id serial primary key, -- id de producto siendo clave primaria
    product_name varchar(150) not null, -- nombre del producto
    description text, -- descripción del producto
    author varchar(150) not null, -- nombre del autor
    release_date varchar(30) not null, -- fecha de salida
    genre varchar(150) not null, -- género
    price_ars numeric(10, 2) not null check (price_ars >= 0) -- precio con dos decimales
);

-- lista de compras
drop table if exists orders cascade;
create table orders (
    order_id serial primary key, -- id de producto siendo clave primaria
    client_id int not null references clients(client_id) on delete cascade, -- puente entre órdenes y clientes
    product_id int not null references products(product_id) on delete restrict, -- puente entre órdenes y productos
    quantity int not null check (quantity > 0), -- cantidad 
    order_date date not null check (order_date >= '2026-06-01' and order_date <= '2026-08-31') -- fecha de compra
);

-- índices de performance
create index idx_orders_client on orders(client_id);
create index idx_orders_product on orders(product_id);
create index idx_orders_date on orders(order_date);

begin;

